"""One Perfect Egg - molten yolk, still warm, shot like a jewel.

Writes the entry picture (a single soft-boiled egg, shell cracked open,
molten golden yolk spilling onto dark slate, sea-salt flakes) to
$MAKEFUN_OUTPUT_DIR/entry.png (default /output/entry.png).

Pure Python standard library only. The picture is embedded below as a
base64 PNG; it is decoded and written out byte for byte, deterministically.
"""

import base64
import hashlib
import os
import struct
import sys

# Base64 PNG data (993x993, 1028852 bytes). Filled in-session from the
# generated picture file; see the build record for how it was produced.
# Integrity constants for the embedded picture: the entry is refused if
# the decoded bytes do not match exactly what was tested locally.
EXPECTED_BYTES = 1028852
EXPECTED_SHA256 = "94f584c7ec3aca635e1103f4b7daec5b9f675b781d3c65160ba5cce6c9d92a87"
MAX_BYTES = 1048576
MAX_DIM = 1024
PNG_B64 = ""


def main():
    try:
        data = base64.b64decode(PNG_B64, validate=True)
    except Exception as exc:  # noqa: BLE001 - bad embedded data is fatal
        print(f"error: could not decode embedded PNG: {exc}", file=sys.stderr)
        return 1
    if data[:8] != b"\x89PNG\r\n\x1a\n":
        print("error: embedded data is not a PNG", file=sys.stderr)
        return 1
    if len(data) != EXPECTED_BYTES:
        print(f"error: decoded {len(data)} bytes, expected {EXPECTED_BYTES}",
              file=sys.stderr)
        return 1
    if hashlib.sha256(data).hexdigest() != EXPECTED_SHA256:
        print("error: decoded PNG does not match expected sha256",
              file=sys.stderr)
        return 1
    width, height = struct.unpack(">II", data[16:24])
    if width > MAX_DIM or height > MAX_DIM or len(data) > MAX_BYTES:
        print(f"error: image {width}x{height} / {len(data)} bytes exceeds "
              f"the {MAX_DIM}x{MAX_DIM} / {MAX_BYTES}-byte cap",
              file=sys.stderr)
        return 1
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as f:
        f.write(data)
    print(f"wrote {path} ({len(data)} bytes)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
